import sys
import math


def main():
    data = sys.stdin.buffer.read()
    lines = data.split(b"\n")
    vals = {}
    get = vals.get
    for line in lines[1:]:
        if not line:
            continue
        parts = line.split(b",")
        if len(parts) < 3:
            continue
        cat = parts[1].decode()
        v = float(parts[2])
        lst = get(cat)
        if lst is None:
            vals[cat] = [v]
        else:
            lst.append(v)
    out = []
    for cat in sorted(vals):
        out.append("%s,%.2f" % (cat, math.fsum(vals[cat])))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


if __name__ == "__main__":
    main()
